const MEMIS_STORAGE_KEYS = [
  "memisAuthData",
  "memisAuthPending",
  "memisCredentials",
  "memisViewSettings",
  "memis_events_endpoint_v4",
  "memis_events_endpoint_v4_oumode",
  "memis_reminders_autostart",
  "memis_reminders_debug",
  "memis_reminders_dedup_v1",
  "dataStore",
  "notificationConfigurations",
  "qrCodesConfig",
];

const MEMIS_COOKIE_NAMES = ["memis_cookie"];

const isMemisStorageKey = (key) =>
  key.toLowerCase().includes("memis") ||
  key.startsWith("localforage/memiscache/") ||
  MEMIS_STORAGE_KEYS.includes(key);

const removeMatchingStorageKeys = (storage) => {
  Object.keys(storage).forEach((key) => {
    if (isMemisStorageKey(key)) {
      storage.removeItem(key);
    }
  });

  MEMIS_STORAGE_KEYS.forEach((key) => storage.removeItem(key));
};

const clearCookie = (name) => {
  ["/", "/memis"].forEach((path) => {
    document.cookie = `${name}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=${path};`;
  });
};

const deleteIndexedDb = (name) =>
  new Promise((resolve) => {
    const request = indexedDB.deleteDatabase(name);
    request.onsuccess = () => resolve();
    request.onerror = () => resolve();
    request.onblocked = () => resolve();
  });

const clearIndexedDbStores = (name) =>
  new Promise((resolve) => {
    const request = indexedDB.open(name);

    request.onerror = () => resolve();
    request.onupgradeneeded = () => {
      request.transaction?.abort();
      resolve();
    };
    request.onsuccess = () => {
      const db = request.result;
      const storeNames = Array.from(db.objectStoreNames);

      if (!storeNames.length) {
        db.close();
        resolve();
        return;
      }

      const transaction = db.transaction(storeNames, "readwrite");
      storeNames.forEach((storeName) => transaction.objectStore(storeName).clear());
      transaction.oncomplete = () => {
        db.close();
        resolve();
      };
      transaction.onerror = () => {
        db.close();
        resolve();
      };
      transaction.onabort = () => {
        db.close();
        resolve();
      };
    };
  });

async function clearMemisStorage() {
  const databaseNames = new Set(["memiscache"]);

  if (indexedDB.databases) {
    const databases = await indexedDB.databases();
    databases.forEach((db) => {
      if (db.name?.toLowerCase().includes("memis")) {
        databaseNames.add(db.name);
      }
    });
  }

  await Promise.all(Array.from(databaseNames).map(clearIndexedDbStores));
  await Promise.all(Array.from(databaseNames).map(deleteIndexedDb));
  removeMatchingStorageKeys(localStorage);
  removeMatchingStorageKeys(sessionStorage);
  MEMIS_COOKIE_NAMES.forEach(clearCookie);
}

const canAccessSettings = async () => {
  try {
    const user = await LocalForageServiceInstance.getItem("userRes", "user");

    const settings = await LocalForageServiceInstance.getItem("dataStore", "dataStore");
    const settingsUserRoles = settings?.settingsUserRoles?.userRoles;
    const hasAccess = user?.userRoles.some((userRole) =>
      settingsUserRoles.some((role) => role?.id === userRole?.id),
    );
    return hasAccess;
  } catch (error) {
    return false;
  }
};

// src/dhis2/dataSetsInit.js

/**
 * Initialize and cache DHIS2 dataSets (dataSets, etc.)
 * This runs once on login to cache frequently accessed dataSets
 */
const dataSetsInit = async (forceRefresh = false) => {
  try {
    // Check if we already have cached dataSets (unless forcing refresh)
    if (!forceRefresh) {
      const cachedDataSets = await LocalForageServiceInstance.getItem(
        "dataSets",
        "dataSets",
      );
      if (
        cachedDataSets &&
        Array.isArray(cachedDataSets) &&
        cachedDataSets.length > 0
      ) {
        console.log(
          "dataSets loaded from cache:",
          cachedDataSets.length,
          "dataSets",
        );
        return null;
      }
    }

    console.log("Fetching dataSets from API...");

    // Fetch all dataSets with their options
    const dataSetsResponse = await dataStore.get(
      "dataSets?fields=id,name,code,periodType,dataInputPeriods,dataSetElements[dataSet[id,name],dataElement[id,name,shortName,formName,displayName,valueType]],organisationUnits[id,name,code],sharing[userGroups[id,name]]&paging=false",
    );

    const dataSets = dataSetsResponse?.data?.dataSets || [];

    // Cache dataSets
    await LocalForageServiceInstance.setItem("dataSets", dataSets, "dataSets");

    console.log(
      "dataSets initialized and cached:",
      dataSets.length,
      "dataSets",
    );
    return null;
  } catch (error) {
    console.error("dataSets initialization failed:", error);
    return error;
  }
};

