async function getEquipmentListOnTransferOutside(event) {
    try {
        const config = await LocalForageServiceInstance.getItem("dataStore", "dataStore");
        const equipmentConfiguration =
            config?.showEquipmentBasedOnPAMLevelOnTransferOutside?.configurations?.find(configItem => configItem?.programId === event?.program);

        if (!equipmentConfiguration) {
            console.warn("No config found for program:", event?.program);
            return {
                equipment: []
            }
        }

        const location = event?.dataValues?.find(dv => dv?.dataElement === equipmentConfiguration?.locationToBeTransferred)?.value;
        const equipment = event?.dataValues?.find(dv => dv?.dataElement === equipmentConfiguration?.equipmentName)?.value;

        const data = await dataStore.get("tracker/trackedEntities", {
            program: equipmentConfiguration?.equipmentProgram,
            orgUnit: location,
            filter: `${equipmentConfiguration?.attribute}:eq:${equipment}`,
            paging: false
        });

        const trackedEntities = data?.data?.trackedEntities;
        if (trackedEntities?.length === 0) {
            return {
                equipment: []
            }
        }

        const events = await dataStore.get(`tracker/events?program=${equipmentConfiguration?.equipmentProgram}&orgUnit=${location}&programStage=${equipmentConfiguration?.stage}&filterAttributes=${equipmentConfiguration?.attribute}:eq:${equipment}&paging=false`);


        const entityIds = trackedEntities?.map(tei => tei?.trackedEntity);
        const notExitingTei = entityIds?.filter(teiEvent => !events?.data?.events?.some(ev => ev?.trackedEntity === teiEvent));
        const available = trackedEntities?.filter(te => notExitingTei?.some(t => t === te?.trackedEntity));

        return {
            equipment: available
        };
    } catch (error) {
        console.error("Error in fetching equipment on Transfer Outside: ", error);
    }
}

