const DE_REFERRAL_DESTINATION_FACILITY = "ZBEn5wUVoaW";

/**
 * Notification handler for referral maintenance approval/decline
 * - ALWAYS notifies the original requester (engineer who created the referral request)
 * - If APPROVED: Also notifies PAM Central users + Biomedical Engineers at the destination facility
 * - If DECLINED: Only notifies the creator
 *
 * Config shape (notificationEvents datastore):
 *   userRoles: [
 *     { id, name, accepted: "true", facilityLevel: "NATIONAL_LEVEL" }  ← PAM Central
 *   ]
 *   destinationFacilityEngineerRoleId: "gCEVDazs2nM"  ← optional override; falls back to this default
 */
const referralMaintenanceApprovalNotification = async (config, options) => {
  try {
    // Fetch the approval event
    const eventData = await dataStore.get(
      `tracker/events/${options?.event}?program=${options?.program}&fields=*`
    );

    if (!eventData?.data) return;

    // Read approval decision
    const approvalDE = eventData?.data?.dataValues?.find(
      (d) => d.dataElement === config?.equipment?.dataElement
    );
    if (!approvalDE?.value) return;

    const approvalValue = String(approvalDE.value).toLowerCase();
    const isApproved = approvalValue === "true" || approvalValue === "yes";
    const actionText = isApproved ? "approved" : "declined";

    const creatorUserId = eventData?.data?.createdBy?.uid;
    if (!creatorUserId) return;

    // Fetch TEI for equipment details
    const teiData = await dataStore.get(
      `tracker/trackedEntities/${options?.teiId}?program=${options?.program}&fields=*`
    );

    const serialNumber = teiData?.data?.attributes?.find(
      (a) => a.attribute === config?.equipment?.serialNumber
    )?.value;

    const equipmentNameAttr = teiData?.data?.attributes?.find(
      (a) => a.attribute === config?.equipment?.equipmentAttribute
    );

    let equipmentLabel = "Equipment";
    if (equipmentNameAttr?.value && config?.equipment?.optionSetId) {
      const optionSets = await LocalForageServiceInstance.getItem("optionSets", "metadata");
      const equip = optionSets?.find((opt) => opt?.id === config?.equipment?.optionSetId);
      const equipmentOption = equip?.options?.find((eq) => eq?.code === equipmentNameAttr.value);
      if (equipmentOption?.name) equipmentLabel = equipmentOption.name;
    }

    const serialLabel = serialNumber ? ` (Serial: ${serialNumber})` : "";

    const ouData = await LocalForageServiceInstance.getItem("organisationUnits", "organisationUnits");
    const ou = ouData?.find((org) => org?.id === eventData?.data?.orgUnit);

    // Build subject and body
    const subject = `Referral maintenance ${actionText}: ${equipmentLabel}${serialLabel} | ${options?.program}.${options?.teiId}.${eventData?.data?.programStage}.${options?.event}`;

    const body = isApproved
      ? `Referral maintenance request for ${equipmentLabel}${serialLabel} has been approved.${ou?.name ? ` Location: ${ou.name}` : ""}`
      : `Your referral maintenance request for ${equipmentLabel}${serialLabel} has been declined.${ou?.name ? ` Location: ${ou.name}` : ""}`;

    // Start with creator
    let recipients = [creatorUserId];

    if (isApproved) {
      // 1. PAM Central users
      const pamCentralRole = config?.userRoles?.find((r) => r.accepted === "true");
      if (pamCentralRole) {
        try {
          const pamResp = await dataStore.get(
            `users.json?paging=false&fields=id&filter=userRoles.id:eq:${pamCentralRole.id}`
          );
          const pamIds = pamResp?.data?.users?.map((u) => u.id) || [];
          recipients.push(...pamIds);
        } catch (e) {
          // non-fatal
        }
      }

      // 2. Biomedical Engineers at the destination facility
      // Read destination facility from the referral event's dataValues
      const destinationFacilityId = eventData?.data?.dataValues?.find(
        (d) => d.dataElement === DE_REFERRAL_DESTINATION_FACILITY
      )?.value;

      if (destinationFacilityId) {
        const engineerRoleId = config?.destinationFacilityEngineerRoleId;

        if (engineerRoleId) {
          try {
            const engResp = await dataStore.get(
              `users.json?paging=false&fields=id&filter=userRoles.id:eq:${engineerRoleId}&filter=organisationUnits.id:eq:${destinationFacilityId}`
            );
            const engIds = engResp?.data?.users?.map((u) => u.id) || [];
            recipients.push(...engIds);
          } catch (e) {
            // non-fatal
          }
        }
      }
    }

    // Deduplicate recipients
    recipients = [...new Set(recipients.filter(Boolean))];

    await sendNotificationHandler(subject, body, recipients);
  } catch (error) {
    // silent fail — notification should not block the approval flow
  }
};

