/**
 * Resolves equipment state config from allocationProcesses in the datastore cache.
 * Returns:
 *   - stateAttributeId  (equipmentStateAttributeId on the programAllocationFields entry)
 *   - allocationStageId (stage.id on the programAllocationFields entry)
 *   - equipmentProgramId (targetProgramId on the programAllocationFields entry)
 */
async function resolveEquipmentStateConfig() {
  const ds = await LocalForageServiceInstance.getItem("dataStore", "dataStore");
  const entry = (ds?.allocationProcesses?.programAllocationFields || []).find(
    (f) => f?.targetProgramType === "WITH_REGISTRATION",
  );

  return {
    stateAttributeId: entry?.equipmentStateAttributeId || null,
    allocationStageId: entry?.stage?.id || null,
    equipmentProgramId: entry?.targetProgramId || null,
  };
}
async function resolveEquipmentStateMaintenance(
  program,
  stage,
  eventId,
  trackedEntity,
  orgUnit,
  state = "MAINTENANCE",
) {
  try {
    if (!program || !stage || !trackedEntity) return null;

    let trackedEntityType = null;
    let resolvedOrgUnit = orgUnit;

    // Load config
    const ds = await LocalForageServiceInstance.getItem(
      "dataStore",
      "dataStore",
    );

    const configs = ds?.maintenanceTagOnTEI?.configurations || [];

    const entry = configs.find(
      (f) =>
        f?.program === program &&
        (f?.stage?.id === stage || f?.stage === stage),
    );

    if (!entry) return null;

    // Get maintenance type from event
    const eventRes = await dataStore.get(
      `tracker/events/${eventId}?fields=dataValues`,
    );

    if (eventRes?.status !== 200 || !eventRes?.data) return null;
    const maintenanceType = eventRes?.data?.dataValues?.find(
      (dv) => dv?.dataElement === entry?.sourceFieldId,
    )?.value;

    // Only proceed if source value matches config
    if (!maintenanceType || maintenanceType !== entry?.sourceValue) {
      return null;
    }

    // Fetch TEI details
    const teiRes = await dataStore.get(
      `tracker/trackedEntities/${trackedEntity}?fields=trackedEntity,orgUnit,trackedEntityType`,
    );

    if (teiRes?.status === 200 && teiRes?.data) {
      trackedEntityType = teiRes.data.trackedEntityType;
      resolvedOrgUnit = teiRes.data.orgUnit || orgUnit;
    }

    if (!trackedEntityType) return null;

    // Update TEI attribute
    const result = await dataStore.post(
      "tracker?async=false&importStrategy=UPDATE",
      {
        trackedEntities: [
          {
            trackedEntity,
            trackedEntityType,
            orgUnit: resolvedOrgUnit,
            attributes: [
              {
                attribute: entry.assignTo,
                value: state,
              },
              {
                attribute: entry.equipStatusId,
                value: entry?.equipStatusValue,
              },
            ],
          },
        ],
      },
    );
    console.log({ result });
  } catch (error) {
    console.error("resolveEquipmentStateMaintenance error:", error);
    return null;
  }
}

/**
 * Updates the Equipment State TEA on a tracked entity.
 * Fetches the TEI first to get the correct trackedEntityType and orgUnit,
 * both of which are required by the DHIS2 tracker UPDATE endpoint.
 *
 * @param {string} trackedEntity - TEI uid
 * @param {string} orgUnit - org unit uid (used as fallback if TEI fetch fails)
 * @param {string} state - state code to set (default: "ALLOCATED")
 */
async function updateEquipmentState(
  trackedEntity,
  orgUnit,
  state = "ALLOCATED",
) {
  if (!trackedEntity) return;

  const { stateAttributeId } = await resolveEquipmentStateConfig();

  if (!stateAttributeId) return;

  // Fetch the TEI to get trackedEntityType and authoritative orgUnit
  let trackedEntityType = null;
  let resolvedOrgUnit = orgUnit;

  try {
    const teiRes = await dataStore.get(
      `tracker/trackedEntities/${trackedEntity}?fields=trackedEntity,orgUnit,trackedEntityType`,
    );
    if (teiRes?.status === 200 && teiRes?.data) {
      trackedEntityType = teiRes.data.trackedEntityType;
      resolvedOrgUnit = teiRes.data.orgUnit || orgUnit;
    }
  } catch (err) {
    console.warn("[updateEquipmentState] TEI fetch error, falling back:", err);
  }

  if (!resolvedOrgUnit) return;

  await dataStore.post("tracker?async=false&importStrategy=UPDATE", {
    trackedEntities: [
      {
        trackedEntity,
        trackedEntityType,
        orgUnit: resolvedOrgUnit,
        attributes: [
          {
            attribute: stateAttributeId,
            value: state,
          },
        ],
      },
    ],
  });
}

/**
 * Marks multiple equipment TEIs as ALLOCATED after bulk event creation.
 *
 * @param {Array} payloadValues - event payloads that were just created (each has trackedEntity + orgUnit)
 */
async function markAllocatedFromEvents(payloadValues = []) {
  const eligible = payloadValues.filter((ev) => ev?.trackedEntity);
  const updates = eligible.map((ev) =>
    updateEquipmentState(ev.trackedEntity, ev.orgUnit, "ALLOCATED"),
  );
  await Promise.allSettled(updates);
}

/**
 * Resolves the allocation stage ID from the datastore config.
 * Used by CreateAttributesController to identify allocation events.
 */
async function resolveAllocationStageId() {
  const { allocationStageId } = await resolveEquipmentStateConfig();
  return allocationStageId;
}

// helper to upload file
async function uploadFile(filePath) {
  const form = new FormData();
  form.append("file", filePath); // `file` is a File object (from input[type=file])
  const res = await dataStore.post("fileResources", form);
  return res?.data?.response?.fileResource?.id;
}

async function buildDataItems(formData, filedataItems, key) {
  const dataItems = [];

  for (const dataItemId of Object.keys(formData)) {
    const value = formData[dataItemId];
    if (
      filedataItems &&
      filedataItems?.includes(dataItemId) &&
      value instanceof File
    ) {
      const fileUid = await uploadFile(value);
      dataItems.push({ [key]: dataItemId, value: fileUid });
    } else {
      dataItems.push({ [key]: dataItemId, value });
    }
  }
  return dataItems;
}

// usage in your payload
async function registerTEI(
  formData,
  fileDataIDs,
  program,
  selectedOrganisationUnit,
  isEdit = false,
  existingEntityId = null,
) {
  try {
    const attributes = await buildDataItems(formData, fileDataIDs, "attribute");
    const date = new Date().toISOString();

    let payload;
    let importStrategy = "CREATE";

    if (isEdit && existingEntityId) {
      // Update existing tracked entity
      const gg = [];
      attributes.map((k) => {
        if (Array.isArray(k.value)) {
          gg.push({
            attribute: k.attribute,
            value: k.value.join(","),
          });
        } else {
          gg.push(k);
        }
      });
      payload = {
        trackedEntity: existingEntityId,
        trackedEntityType: program?.trackedEntityType?.id,
        orgUnit: selectedOrganisationUnit,
        attributes: gg,
      };
      importStrategy = "UPDATE";
    } else {
      // Create new tracked entity
      payload = {
        trackedEntityType: program?.trackedEntityType?.id,
        orgUnit: selectedOrganisationUnit,
        attributes,
        enrollments: [
          {
            attributes,
            enrolledAt: date,
            occurredAt: date,
            orgUnit: selectedOrganisationUnit,
            program: program?.id,
            trackedEntityType: program?.trackedEntityType?.id,
            status: "ACTIVE",
          },
        ],
      };
    }

    const response = await dataStore.post(
      `tracker?async=false&importStrategy=${importStrategy}`,
      { trackedEntities: [payload] },
    );
    if (importStrategy === "CREATE") {
      const teiId =
        response?.data?.bundleReport?.typeReportMap?.TRACKED_ENTITY
          ?.objectReports?.[0]?.uid;
      const configData = await getNotificationEvent(
        program?.id,
        importStrategy,
      );

      await notificationSendTrigger(configData?.event, {
        orgUnit: selectedOrganisationUnit,
        program: program?.id,
        count: 1,
        teiId,
      });
    }
    return response;
  } catch (error) {
    return error;
  }
}

async function registerMultipleTEI(
  formData,
  fileDataIDs,
  program,
  selectedOrganisationUnit,
  commonData,
) {
  try {
    const date = new Date().toISOString();
    const importStrategy = "CREATE";

    const formEntries = Array.isArray(formData) ? formData : [formData];
    const uploadedFilesCache = new Map(); // track uploaded files for common attributes
    const allPayloads = [];

    const commonAttributes = Object.keys(commonData); // attributes to deduplicate

    for (const entry of formEntries) {
      const mergedData = { ...commonData, ...entry };

      // Build attributes for this entry only
      const attributes = [];

      for (const dataItemId of Object.keys(mergedData)) {
        const value = mergedData[dataItemId];

        if (fileDataIDs?.includes(dataItemId) && value instanceof File) {
          let fileUid;

          // Deduplicate if this attribute is common
          if (
            commonAttributes.includes(dataItemId) &&
            uploadedFilesCache.has(dataItemId)
          ) {
            fileUid = uploadedFilesCache.get(dataItemId);
          } else {
            fileUid = await uploadFile(value);
            if (commonAttributes.includes(dataItemId)) {
              uploadedFilesCache.set(dataItemId, fileUid);
            }
          }

          attributes.push({ attribute: dataItemId, value: fileUid });
        } else if (Array.isArray(value)) {
          for (const v of value) {
            attributes.push({ attribute: dataItemId, value: v });
          }
        } else {
          attributes.push({ attribute: dataItemId, value });
        }
      }

      const payload = {
        trackedEntityType: program?.trackedEntityType?.id,
        orgUnit: selectedOrganisationUnit,
        attributes,
        enrollments: [
          {
            attributes,
            enrolledAt: date,
            occurredAt: date,
            orgUnit: selectedOrganisationUnit,
            program: program?.id,
            trackedEntityType: program?.trackedEntityType?.id,
            status: "ACTIVE",
          },
        ],
      };

      allPayloads.push(payload);
    }

    // Send all TEIs at once
    const response = await dataStore.post(
      `tracker?async=false&importStrategy=${importStrategy}`,
      { trackedEntities: allPayloads },
    );

    if (importStrategy === "CREATE") {
      const teiId =
        response?.data?.bundleReport?.typeReportMap?.TRACKED_ENTITY?.objectReports?.map(
          (ids) => ids?.uid,
        );

      await notificationSendTrigger("EQUIPMENT_REGISTRATION_CREATE", {
        orgUnit: selectedOrganisationUnit,
        program: program?.id,
        count: allPayloads?.ength,
        teiId: teiId[0],
      });
    }
    return response;
  } catch (error) {
    console.error("Error registering multiple TEIs:", error);
  }
}

async function programWithoutRegistration(
  formData,
  fileDataIDs,
  program,
  selectedOrganisationUnit,
  isEdit = false,
  existingEventId = null,
  occurredAt = null,
) {
  try {
    delete formData.undefined;
    const dataItemsValues = await buildDataItems(
      formData,
      fileDataIDs,
      "dataElement",
    );

    // FIX: Convert arrays to comma-separated strings for Multi text fields
    const processedDataValues = dataItemsValues.map((item) => {
      if (Array.isArray(item.value)) {
        return {
          ...item,
          value: item.value.join(","),
        };
      }
      return item;
    });

    const date = new Date().toISOString();

    let payload;
    let importStrategy = "CREATE";

    if (isEdit && existingEventId) {
      // Update existing event
      payload = {
        event: existingEventId,
        orgUnit: selectedOrganisationUnit,
        program: program?.id,
        occurredAt: occurredAt,
        dataValues: processedDataValues?.filter(
          (de) => de?.dataElement !== "createdBy",
        ),
      };
      importStrategy = "UPDATE";
    } else {
      // Create new event
      const taskStatus = await LocalForageServiceInstance.getItem(
        "dataStore",
        "dataStore",
      );

      if (!taskStatus) return null;

      // const data = taskStatus;
      const taskData = taskStatus?.taskStatusPrefill;

      // No taskStatusPrefill stored
      if (taskData && taskData?.programId === program?.id) {
        processedDataValues.push({
          dataElement: taskData?.sourceId,
          value: taskData?.value,
        });
      }

      payload = {
        orgUnit: selectedOrganisationUnit,
        program: program?.id,
        occurredAt: date,
        dataValues: processedDataValues,
      };
    }

    const response = await dataStore.post(
      `tracker?async=false&importStrategy=${importStrategy}`,
      { events: [payload] },
    );

    if (importStrategy === "CREATE") {
      const teiId =
        response?.data?.bundleReport?.typeReportMap?.EVENT?.objectReports?.[0]
          ?.uid;

      // Check if this is the reports program — if so, skip creation notification.
      // Reports send their notification on "Submit for Review" (Draft → Under Review) instead.
      const dataStoreData = await LocalForageServiceInstance.getItem(
        "dataStore",
        "dataStore",
      );
      const reportTypesConfig = dataStoreData?.reportTypesConfigurations;
      const isReportsProgram = reportTypesConfig?.programId === program?.id;

      if (!isReportsProgram) {
        const configData = await getNotificationEvent(
          program?.id,
          importStrategy,
        );

        await notificationSendTrigger(configData?.event, {
          orgUnit: selectedOrganisationUnit,
          program: program?.id,
          count: 1,
          teiId,
          event: teiId,
        });
      }
    }
    return response;
  } catch (error) {
    console.log(error);
  }
}

// usage in your payload
async function programWithRegistrationEvent(
  formData,
  fileDataIDs,
  program,
  selectedOrgUnit,
  trackedEntity,
  programStage,
  eventDate,
  enrollment,
  isEdit = false,
  existingEventId = null,
  options = {},
) {
  try {
    const values = await buildDataItems(formData, fileDataIDs, "dataElement");
    const equipmentDetails = await dataStore.get(
      "tracker/trackedEntities/" + trackedEntity + "?fields=*",
    );

    let payload;
    let importStrategy = "CREATE";

    if (isEdit && existingEventId) {
      // Update existing event
      payload = {
        event: existingEventId,
        enrollment: equipmentDetails?.data?.enrollments?.[0]?.enrollment,
        programStage,
        program: program?.id,
        orgUnit: selectedOrgUnit || null,
        eventDate,
        occurredAt: eventDate,
        trackedEntity,
        status: "ACTIVE",
        dataValues: values,
      };
      importStrategy = "UPDATE";
    } else {
      // Create new event
      payload = {
        enrollment: equipmentDetails?.data?.enrollments?.[0]?.enrollment,
        programStage,
        program: program?.id,
        orgUnit: selectedOrgUnit || null, // safe fallback
        eventDate,
        occurredAt: eventDate,
        trackedEntity,
        status: "ACTIVE",
        dataValues: values, // must be an array of { dataElement, value }
      };
    }

    const response = await dataStore.post(
      `tracker?async=false&importStrategy=${importStrategy}`,
      { events: [payload] },
    );

    if (importStrategy === "CREATE") {
      const teiId =
        response?.data?.bundleReport?.typeReportMap?.EVENT?.objectReports?.[0]
          ?.uid;

      if (!teiId) {
        const rawMessage = response?.message || response?.data?.message || "";
        let parsedMessage = "";

        try {
          const parsed =
            typeof rawMessage === "string" ? JSON.parse(rawMessage) : rawMessage;
          const reports = parsed?.validationReport?.errorReports || [];
          parsedMessage =
            reports
              .map((report) => report?.message || report?.errorCode)
              .filter(Boolean)
              .join(", ") || parsed?.message || "";
        } catch {
          parsedMessage = typeof rawMessage === "string" ? rawMessage : "";
        }

        throw new Error(
          parsedMessage || "Tracker event creation failed on the server.",
        );
      }

      // If this is an allocation event, mark the equipment as ALLOCATED
      const allocationStageId = await resolveAllocationStageId();
      if (
        allocationStageId &&
        programStage === allocationStageId &&
        trackedEntity
      ) {
        await updateEquipmentState(trackedEntity, selectedOrgUnit, "ALLOCATED");
      }

      if (programStage) {
        await resolveEquipmentStateMaintenance(
          program?.id,
          programStage,
          teiId,
          trackedEntity,
          selectedOrgUnit,
          "MAINTENANCE",
        );
      }
      if (!options?.skipNotifications) {
        const configData = await getNotificationEvent(
          program?.id,
          (importStrategy = "STAGE_CREATE"),
          programStage,
        );

        await notificationSendTrigger(configData?.event, {
          orgUnit: selectedOrgUnit,
          program: program?.id,
          event: null,
          count: 1,
          teiId,
          payload,
          trackedEntity,
          events:
            response?.data?.bundleReport?.typeReportMap?.EVENT?.objectReports.map(
              (b) => b?.uid,
            ),
          equipmentDetails: equipmentDetails?.data,
        });
      }
    }
    return response;
  } catch (error) {
    console.log({ error });
    throw error;
  }
}
