const escapeRegex = (value) =>
  String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const decodeScannedQrText = (raw) => {
  const input = String(raw ?? "").trim();
  if (!input) return "";

  try {
    const parsed = JSON.parse(input);
    if (typeof parsed === "string") return parsed.trim();
    if (parsed && typeof parsed === "object") return JSON.stringify(parsed);
  } catch (_) {}

  return input;
};

const extractLineValue = (text, keyLabel) => {
  if (!text || !keyLabel) return "";
  const re = new RegExp(`^\\s*${escapeRegex(keyLabel)}\\s*:\\s*(.+)$`, "im");
  const match = text.match(re);
  return String(match?.[1] || "").trim();
};

const extractSearchValueFromQr = (rawScannedValue, qrConfig = null) => {
  const decoded = decodeScannedQrText(rawScannedValue);
  if (!decoded) return "";

  const searchName = qrConfig?.searchKey?.name;
  if (searchName) {
    const bySearchName = extractLineValue(decoded, searchName);
    if (bySearchName) return bySearchName;
  }

  const searchId = qrConfig?.searchKey?.id;
  const configuredName = searchId
    ? qrConfig?.source?.values?.[searchId]?.name
    : null;
  if (configuredName) {
    const byConfiguredName = extractLineValue(decoded, configuredName);
    if (byConfiguredName) return byConfiguredName;
  }

  const knownKeys = [
    "Serial Number",
    "Part Number",
    "Equipment ID",
    "Spare Part Name",
    "Equipment Name",
  ];
  for (const key of knownKeys) {
    const value = extractLineValue(decoded, key);
    if (value) return value;
  }

  const firstKeyValue = decoded
    .split(/\r?\n/)
    .map((line) => line.trim())
    .find((line) => line.includes(":"));
  if (firstKeyValue) {
    return String(firstKeyValue.split(":").slice(1).join(":") || "").trim();
  }

  return decoded;
};

const resolveQrSearchQuery = async ({ rawScannedValue, programId }) => {
  const decoded = decodeScannedQrText(rawScannedValue);
  if (!decoded) return "";

  try {
    const store = await LocalForageServiceInstance.getItem(
      "dataStore",
      "dataStore"
    );
    const qrConfig = store?.qrCodesConfigurations?.configurations?.find(
      (cfg) => cfg?.source?.programId === programId
    );
    return extractSearchValueFromQr(decoded, qrConfig);
  } catch (_) {
    return extractSearchValueFromQr(decoded, null);
  }
};

const hasQrSearchConfigForProgram = async (programId) => {
  if (!programId) return false;
  try {
    const store = await LocalForageServiceInstance.getItem(
      "dataStore",
      "dataStore"
    );
    const config = store?.qrCodesConfigurations?.configurations?.find(
      (cfg) => cfg?.source?.programId === programId
    );
    return Boolean(config?.searchKey?.id || config?.searchKey?.name);
  } catch (_) {
    return false;
  }
};

const normalizeLabel = (value) =>
  String(value || "")
    .trim()
    .toLowerCase();

const baseId = (value) => String(value || "").split("?")[0];

const isInventoryNavigationItem = (item) => {
  if (!item || typeof item !== "object") return false;
  const label = normalizeLabel(item?.name || item?.displayName);
  return label === "inventory";
};

const isInventoryNavigationContext = (menuItems = [], currentId = "") => {
  const list = Array.isArray(menuItems) ? menuItems : [];
  const exact = list.find((item) => String(item?.id || "") === String(currentId || ""));
  if (isInventoryNavigationItem(exact)) return true;

  const currentBase = baseId(currentId);
  const byBase = list.find((item) => baseId(item?.id) === currentBase);
  return isInventoryNavigationItem(byBase);
};

