		    PDF417CodewordDecoder.bSymbolTableReady = false;
		    PDF417CodewordDecoder.RATIOS_TABLE = new Array(PDF417Common.SYMBOL_TABLE.length).map(x => new Array(PDF417Common.BARS_IN_MODULE));

