async function createQrDataUrl(payloadStr, size = 320) {
  return QRCode.toDataURL(payloadStr, {
    width: size,
    margin: 1,
    errorCorrectionLevel: "M",
  });
}

// Save the QR using the same native/web behavior used elsewhere in the app.
async function downloadQrFile(payloadStr, filename) {
  const platform = Capacitor.getPlatform();

  if (platform === "android" || platform === "ios") {
    const dataUrl = await QRCode.toDataURL(payloadStr, {
      width: 512,
      margin: 1,
      errorCorrectionLevel: "M",
    });
    const base64Data = dataUrl.split(",")[1];
    let saveTarget = {
      directory: Directory.Documents,
      path: filename,
    };

    if (platform === "android") {
      try {
        const permission = await Filesystem.checkPermissions();
        if (permission?.publicStorage !== "granted") {
          const requested = await Filesystem.requestPermissions();
          if (requested?.publicStorage !== "granted") {
            throw new Error("storage permission denied");
          }
        }

        await Filesystem.writeFile({
          path: `Download/${filename}`,
          data: base64Data,
          directory: Directory.ExternalStorage,
          recursive: true,
        });
        saveTarget = {
          directory: Directory.ExternalStorage,
          path: `Download/${filename}`,
        };
      } catch (error) {
        if (String(error?.message || "").toLowerCase().includes("storage permission denied")) {
          throw error;
        }

        await Filesystem.writeFile({
          path: filename,
          data: base64Data,
          directory: Directory.Documents,
          recursive: true,
        });
      }
    } else {
      await Filesystem.writeFile({
        path: filename,
        data: base64Data,
        directory: Directory.Documents,
        recursive: true,
      });
    }

    try {
      const uri = await Filesystem.getUri(saveTarget);
      if (uri?.uri && typeof window !== "undefined") {
        window.open(uri.uri, "_blank");
      }
    } catch (_) {
    }

    return "saved";
  }

  await downloadQrPng(payloadStr, filename, 512);
  return "downloaded";
}

async function printQrCode(dataUrl, title = "PAM Equipment") {
  if (!dataUrl) {
    throw createQrFlowError("The QR code preview is not ready for printing.");
  }

  const htmlContent = `
    <html>
      <head>
        <style>
          html, body {
            height: 100%;
            margin: 0;
            padding: 0;
            background: #fff;
          }
          body {
            display: flex;
            justify-content: center;
            align-items: center;
            flex-direction: column;
            font-family: sans-serif;
            text-align: center;
          }
          h3 {
            margin-bottom: 16px;
          }
          img {
            width: 300px;
          }
        </style>
      </head>
      <body>
        <h3>${title}</h3>
        <img src="${dataUrl}" alt="${title}" />
      </body>
    </html>
  `;

  if (Capacitor.getPlatform() === "android" || Capacitor.getPlatform() === "ios") {
    await Printer.print({
      content: htmlContent,
      name: title,
      orientation: "portrait",
    });
    return "printed";
  }

  const w = typeof window !== "undefined" ? window : null;
  if (!w) {
    throw createQrFlowError("Printing is not available in this environment.");
  }

  const width = w.screen?.availWidth || 1200;
  const height = w.screen?.availHeight || 900;
  const printWindow = w.open(
    "",
    "_blank",
    `toolbar=no,scrollbars=yes,resizable=yes,top=0,left=0,width=${width},height=${height}`
  );

  if (!printWindow) {
    throw createQrFlowError("The print window was blocked. Allow pop-ups and try again.");
  }

  printWindow.document.open();
  printWindow.document.write(htmlContent);
  printWindow.document.close();
  printWindow.focus();
  printWindow.print();
  return "printed";
}

const DEFAULT_ENTITY_LABEL = "Equipment";

function getQrEntityLabel(dataStoreData, programId) {
  const configurations = Array.isArray(
    dataStoreData?.qrCodeLabels?.configurations,
  )
    ? dataStoreData.qrCodeLabels.configurations
    : [];

  const match = configurations.find(
    (config) => config?.programId && config.programId === programId,
  );

  const label = String(match?.entityLabel || "").trim();
  return label || DEFAULT_ENTITY_LABEL;
}

