    return {
      access: false,
    };

  // No stageAddButtonAccess stored
  if (!raw?.stageAddButtonAccess) {
    return {
      access: false,
    };
  }

  const record = raw?.stageAddButtonAccess?.configs?.find(
    (v) => v?.programId === programId && v?.stageId === stageId
  );

  // If there is no record for this program
  if (!record) {
    return {
      access: false,
    };
  }

