const taskController = async (event) => {
  try {
    const data = await LocalForageServiceInstance.getItem("dataStore", "dataStore");
    const loggedInUser = await LocalForageServiceInstance.getItem("userRes", "user");

    const canRegister =
      data?.showTaskRegisterButtonByUserRole?.userRoles?.some(role =>
        loggedInUser?.userRoles?.some(userRole => userRole?.id === role?.id)
      ) ?? false;

    const taskConfig = data?.taskHideButtonWhenDone;

    // Default response
    const defaultResponse = {
      canRegister,
      showButton: true,
    };

    if (!data || !taskConfig) return defaultResponse;

    if (event?.program !== taskConfig?.programId) {
      return defaultResponse;
    }

    const taskStatus = event?.dataValues?.find(
      v => v?.dataElement === taskConfig?.source
    );

    if (!taskStatus) return defaultResponse;

    return {
      canRegister,
      showButton: taskStatus?.value !== taskConfig?.value,
    };
  } catch (error) {
    return {
      canRegister: false,
      showButton: true,
    };
  }
};

