// Approval status configuration utilities
// Helper function to get approval field ID for a program from datastore config
const getApprovalFieldId = (programId, approvalStatusConfig) => {
    if (!approvalStatusConfig?.programs) return null;

    const config = approvalStatusConfig.programs.find(
        c => c.programId === programId
    );
    return config?.approvalFieldId || null;
};

// Helper function to check if a program has approval status configured
const hasApprovalStatus = (programId, approvalStatusConfig) => {
    if (!approvalStatusConfig?.programs) return false;

    return approvalStatusConfig.programs.some(
        c => c.programId === programId
    );
};

