const hideCollectionIfHasValue = (event, section,) => {

    const dataValues = event?.dataValues;
    const fields = section?.fields;
    // If there is no section or no fields, do not hide the button
    if (!Array.isArray(dataValues) || !dataValues?.length) return false;

    // Hide if at least one field already has a value
    const hide = dataValues?.some((dv) =>
        fields?.some((field) => field?.id === dv?.dataElement)
    );
    return !hide
};

const hideApprovalButtonBasedOnTransferType = async (event, user) => {
    if (!event || !user) return false;

    const store = await LocalForageServiceInstance.getItem("dataStore", "dataStore");

    const configs =
        store?.transferShowApprovalButtonAccess?.configurations;
    // 1. Filter by program
    const programConfigs = configs.filter(
        cfg => cfg?.programId === event?.program
    );

    if (!programConfigs.length) return true;

    // 2. Resolve active transferLocationType field + value
    const transferEntry = event?.dataValues?.find(dv =>
        programConfigs.some(cfg =>
            Array.isArray(cfg?.transferLocationType)
                ? cfg?.transferLocationType.includes(dv?.dataElement)
                : cfg?.transferLocationType === dv?.dataElement
        )
    );

    if (!transferEntry?.value) return false;

    const transferTypeValue = transferEntry?.value;

    // 3. Match configuration by transfer type value
    const matchedConfig = programConfigs?.find(
        cfg => cfg?.transferLocationTypeValue === transferTypeValue
    );

    if (!matchedConfig) return false;
    // if (matchedConfig?.section !== section) return false;
    // 4. Role check
    const allowedRoles = Array.isArray(matchedConfig?.userRoles)
        ? matchedConfig.userRoles
        : [];

    const userRoleIds = Array.isArray(user?.userRoles)
        ? user?.userRoles.map(r => r?.id)
        : [];

    const hasAccess = allowedRoles?.some(roleId =>
        userRoleIds?.includes(roleId)
    );

    // Return TRUE to show, FALSE to hide
    return hasAccess;
};

