const hideUpdateButtonAfterEquipmentIsCollected = async (field) => {
  try {
    const data = await LocalForageServiceInstance.getItem("dataStore", "dataStore");
    if (!data || !data?.equipmentCollectionHideUpdate)
      return {
        showButton: true,
      };
    const task = data?.equipmentCollectionHideUpdate;

    if (field?.program !== task?.programId)
      return {
        showButton: true,
      };
    const target = field?.dataValues?.find(
      (f) => f.dataElement === task?.fieldId
    );

    if (!target)
      return {
        showButton: true,
      };
    if (
      target?.value.trim() === "" ||
      target?.value === null ||
      target?.value === undefined
    ) {
      return {
        showButton: true,
      };
    } else {
      return {
        showButton: false,
      };
    }
  } catch (error) {
    return {
      showButton: true,
    };
  }
};

const hideAcknowledgeButton = async (allocationData) => {
  try {
    const data = await LocalForageServiceInstance.getItem("dataStore", "dataStore");
    if (!data || !data?.prefillReceiverNameEquipment)
      return { showButton: true };

    const task = data?.prefillReceiverNameEquipment;

    if (allocationData?.program !== task?.programId)
      return { showButton: true };

    const source = allocationData?.dataValues?.find(
        (f) => f.dataElement === task?.sourceId
    );

    const target = allocationData?.dataValues?.find(
        (f) => f.dataElement === task?.targetId
    );

    // Collection not yet done — hide
    if (!source?.value || source.value.trim() === "")
      return { showButton: false };

    // Already acknowledged (target pre-filled) — hide
    if (target?.value && target.value.trim() !== "")
      return { showButton: false };

    // Collected but not yet acknowledged — show
    return { showButton: true };
  } catch (error) {
    return { showButton: true };
  }
};

